import{_ as s,C as n,o as t,c as o,a2 as e,b as i,w as d,a as l,E as v,a3 as c}from"./chunks/framework.CZqXuAiL.js";const y=JSON.parse(`{"title":"Glacier Pack for Pterodactyl","description":"A family of 46 standalone addons for Pterodactyl Panel v1.12.x plus the Glacier Pack hub — a single custom admin dashboard that hosts every addon's complete management UI in one Glacier-styled page.","frontmatter":{"title":"Glacier Pack for Pterodactyl","description":"A family of 46 standalone addons for Pterodactyl Panel v1.12.x plus the Glacier Pack hub — a single custom admin dashboard that hosts every addon's complete management UI in one Glacier-styled page."},"headers":[],"relativePath":"glacier-pack/index.md","filePath":"glacier-pack/index.md","lastUpdated":1786286622000}`),h={name:"glacier-pack/index.md"};function g(p,a,u,m,f,k){const r=n("Mermaid");return t(),o("div",null,[a[1]||(a[1]=e('<h1 id="glacier-pack-for-pterodactyl" tabindex="-1" data-v-92836ea9>Glacier Pack for Pterodactyl <a class="header-anchor" href="#glacier-pack-for-pterodactyl" aria-label="Permalink to &quot;Glacier Pack for Pterodactyl&quot;" data-v-92836ea9>​</a></h1><p data-v-92836ea9><strong data-v-92836ea9>A family of 46 standalone addons for Pterodactyl Panel v1.12.x, managed from one hub.</strong> Glacier Pack installs as self-contained packages — no Blueprint, no module daemons on your nodes — and replaces the sprawl of 46 separate admin pages with a single custom dashboard at <code data-v-92836ea9>/admin/glacier-pack</code> that hosts every addon&#39;s complete management UI in one Glacier-styled page.</p><div class="tip custom-block" style="margin-top:1.5rem;" data-v-92836ea9><p data-v-92836ea9><strong data-v-92836ea9>Built for PingLess Studios</strong><a href="https://studio.pingless.org" target="_blank" rel="noreferrer" data-v-92836ea9>studio.pingless.org</a> · Standalone packages, installed directly on the panel</p></div><hr data-v-92836ea9><h2 id="architecture" tabindex="-1" data-v-92836ea9>Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;" data-v-92836ea9>​</a></h2>',5)),(t(),i(c,null,{default:d(()=>[v(r,{id:"mermaid-15",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Pack%5B%22Glacier%20Addons%20family%20(46%20addons)%22%5D%0A%20%20%20%20%20%20%20%20BASIC%5B%22Basic%20pack%3Cbr%2F%3E18%20addons%22%5D%0A%20%20%20%20%20%20%20%20ADV%5B%22Advanced%20pack%3Cbr%2F%3E28%20addons%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Panel%5B%22Pterodactyl%20Panel%20v1.12.x%22%5D%0A%20%20%20%20%20%20%20%20HUB%5B%22Glacier%20Pack%20hub%3Cbr%2F%3E%2Fadmin%2Fglacier-pack%22%5D%0A%20%20%20%20%20%20%20%20EP%5B%22Addon%20action%20endpoints%3Cbr%2F%3EPOST%20%2F%20DELETE%20routes%22%5D%0A%20%20%20%20%20%20%20%20CLIENT%5B%22Client-facing%20surfaces%3Cbr%2F%3Econsole%20%C2%B7%20files%20%C2%B7%20account%20%C2%B7%20network%22%5D%0A%20%20%20%20%20%20%20%20BASIC%20--%3E%20HUB%0A%20%20%20%20%20%20%20%20ADV%20--%3E%20HUB%0A%20%20%20%20%20%20%20%20HUB%20--%3E%7C%22_hub%20return%20URL%22%7C%20EP%0A%20%20%20%20%20%20%20%20BASIC%20--%3E%20CLIENT%0A%20%20%20%20%20%20%20%20ADV%20--%3E%20CLIENT%0A%20%20%20%20end%0A%0A%20%20%20%20ADMIN%5B%22Root%20admin%22%5D%20--%3E%7Cone%20sidebar%20tab%7C%20HUB%0A%20%20%20%20USERS%5B%22Panel%20users%22%5D%20--%3E%20CLIENT%0A"})]),fallback:d(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p data-v-92836ea9>The hub is the <strong data-v-92836ea9>only admin surface</strong>. Each addon&#39;s original admin pages and sidebar links are removed on install; everything an admin could do there — every table, form, action, filter and stat — renders inside a hub pane instead. Forms still post to each addon&#39;s own endpoints and land back on the same pane, so nothing about how the addons work changes — only where you manage them.</p><hr data-v-92836ea9><h2 id="key-features" tabindex="-1" data-v-92836ea9>Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;" data-v-92836ea9>​</a></h2><ul data-v-92836ea9><li data-v-92836ea9><strong data-v-92836ea9>One admin dashboard for everything.</strong> A single &quot;Glacier Pack&quot; sidebar tab opens a standalone, full-page admin UI styled after the Glacier theme editor — near-black surfaces, teal accent, its own chrome (not AdminLTE). Root-admin only, guarded twice.</li><li data-v-92836ea9><strong data-v-92836ea9>46 addons, two packs.</strong> The Basic pack covers panel operations (recycle bin, URL downloads, logs, alerts, uptime, audit trail, schedule/startup presets, PWA shell); the Advanced pack covers hosting workflows (S3 backups, plugin/mod/modpack installers, staff delegation, subdomains, server imports, world and version management, game-specific tooling).</li><li data-v-92836ea9><strong data-v-92836ea9>Full pages in-hub, not summaries.</strong> Each addon renders its complete original UI as a hub pane — tables, forms, pagination, stat cards — with pill-style sub-tabs for multi-page addons.</li><li data-v-92836ea9><strong data-v-92836ea9>Uniform save flow.</strong> Every form carries a <code data-v-92836ea9>_hub</code> return URL; successful saves land back on the same pane with a success banner, and validation errors render in a hub-styled callout above the form.</li><li data-v-92836ea9><strong data-v-92836ea9>Standalone packaging, zero framework dependencies.</strong> Every addon is a self-contained directory that mirrors the panel root (<code data-v-92836ea9>PanelFiles/</code>) with an idempotent <code data-v-92836ea9>data/install.sh</code> installer — no Blueprint, no external CDN assets, no core-file replacement (marker-delimited patches only).</li><li data-v-92836ea9><strong data-v-92836ea9>Client surfaces without rebuilds.</strong> Addons ship their client UI as static JS/CSS loaded at runtime — no <code data-v-92836ea9>yarn build</code> (Recycle Bin additionally offers an optional compiled SPA integration). The panel&#39;s React app is enhanced, never forked.</li><li data-v-92836ea9><strong data-v-92836ea9>Glacier theme compatible.</strong> Client-facing addon styles consume Glacier design tokens (<code data-v-92836ea9>var(--gl-*, fallback)</code>), so every addon inherits Glacier&#39;s accent, surfaces and radius when the theme is installed — and keeps its own look when it isn&#39;t.</li><li data-v-92836ea9><strong data-v-92836ea9>Safe delegation built in.</strong> Permission Manager gives staff a restricted admin area at <code data-v-92836ea9>/admin/staff</code> with real, auto-provisioned Pterodactyl subusers — no <code data-v-92836ea9>root_admin</code> grants, enforced by the panel itself.</li><li data-v-92836ea9><strong data-v-92836ea9>Idempotent installers.</strong> Every <code data-v-92836ea9>install.sh</code> is safe to re-run (and should be re-run after panel updates overwrite patched files), registers one service provider, runs migrations, and clears caches.</li></ul><hr data-v-92836ea9><h2 id="quick-install" tabindex="-1" data-v-92836ea9>Quick Install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick Install&quot;" data-v-92836ea9>​</a></h2><p data-v-92836ea9>Install the hub first — it is the only admin surface for the whole family:</p><div class="language-bash vp-adaptive-theme" data-v-92836ea9><button title="Copy Code" class="copy" data-v-92836ea9></button><span class="lang" data-v-92836ea9>bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-92836ea9><code data-v-92836ea9><span class="line" data-v-92836ea9><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;" data-v-92836ea9>cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-92836ea9> glacier-pack</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" data-v-92836ea9> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-92836ea9>sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-92836ea9> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-92836ea9> data/install.sh</span></span></code></pre></div><p data-v-92836ea9>Then install any addon the same way:</p><div class="language-bash vp-adaptive-theme" data-v-92836ea9><button title="Copy Code" class="copy" data-v-92836ea9></button><span class="lang" data-v-92836ea9>bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-92836ea9><code data-v-92836ea9><span class="line" data-v-92836ea9><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;" data-v-92836ea9>cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-92836ea9> recycle-bin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" data-v-92836ea9> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-92836ea9>sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-92836ea9> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-92836ea9> data/install.sh</span></span></code></pre></div><p data-v-92836ea9>Open <strong data-v-92836ea9>Admin → Glacier Pack</strong> (or <code data-v-92836ea9>/admin/glacier-pack</code>) as a root admin. See <a href="./getting-started/installation" data-v-92836ea9>Installation</a> for prerequisites, verification and troubleshooting.</p><hr data-v-92836ea9><h2 id="pack-contents" tabindex="-1" data-v-92836ea9>Pack Contents <a class="header-anchor" href="#pack-contents" aria-label="Permalink to &quot;Pack Contents&quot;" data-v-92836ea9>​</a></h2><h3 id="basic-pack-—-18-addons" tabindex="-1" data-v-92836ea9>Basic pack — 18 addons <a class="header-anchor" href="#basic-pack-—-18-addons" aria-label="Permalink to &quot;Basic pack — 18 addons&quot;" data-v-92836ea9>​</a></h3><table tabindex="0" data-v-92836ea9><thead data-v-92836ea9><tr data-v-92836ea9><th data-v-92836ea9>Addon</th><th data-v-92836ea9>Purpose</th></tr></thead><tbody data-v-92836ea9><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Audit Log</strong></td><td data-v-92836ea9>Filterable trail of everything the panel&#39;s activity feed records.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Auto Suspend</strong></td><td data-v-92836ea9>Per-server expiry dates with warning emails, suspension and optional auto-delete.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Command History</strong></td><td data-v-92836ea9>Per-server console command history with one-click re-run.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Config Editor</strong></td><td data-v-92836ea9>Edit the panel&#39;s <code data-v-92836ea9>.env</code> safely from the browser, with backups and validation.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Console Log Share</strong></td><td data-v-92836ea9>One-click console log copying and sharing from the server console.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Login Activity</strong></td><td data-v-92836ea9>Record of every sign-in, with geolocation, VPN flags and session revocation.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Move Files</strong></td><td data-v-92836ea9>Browsable directory picker for the file manager move/copy dialog.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Node Status</strong></td><td data-v-92836ea9>Uptime graphs, incidents, custom monitors and a public status page.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Panel Logs</strong></td><td data-v-92836ea9>Live view of the panel&#39;s own log files (plus nginx/Wings sources), no SSH required.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>PWA</strong></td><td data-v-92836ea9>Installable app shell with service-worker caching and an offline page.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Quick Files</strong></td><td data-v-92836ea9>Pin files and folders as one-click chips in the file manager.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Recycle Bin</strong></td><td data-v-92836ea9>Recoverable file deletion with quotas and per-egg retention windows.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Resource Alerts</strong></td><td data-v-92836ea9>Threshold notifications the moment a server crosses a usage limit.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Schedule Presets</strong></td><td data-v-92836ea9>Admin-defined schedule templates users apply in one click.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Server Timezone</strong></td><td data-v-92836ea9>Per-server IANA timezone delivered to the container as <code data-v-92836ea9>TZ</code>.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Server Wiper</strong></td><td data-v-92836ea9>Scheduled and on-demand file wipes with Rust map-rotation options.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Startup Presets</strong></td><td data-v-92836ea9>Admin-approved startup commands applied from the Startup page.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>URL Download</strong></td><td data-v-92836ea9>Fetch remote files straight into a server from the file manager.</td></tr></tbody></table><h3 id="advanced-pack-—-28-addons" tabindex="-1" data-v-92836ea9>Advanced pack — 28 addons <a class="header-anchor" href="#advanced-pack-—-28-addons" aria-label="Permalink to &quot;Advanced pack — 28 addons&quot;" data-v-92836ea9>​</a></h3><table tabindex="0" data-v-92836ea9><thead data-v-92836ea9><tr data-v-92836ea9><th data-v-92836ea9>Addon</th><th data-v-92836ea9>Purpose</th></tr></thead><tbody data-v-92836ea9><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Ark Mod Installer</strong></td><td data-v-92836ea9>CurseForge (ASA) and Steam Workshop (ASE) mod management for ARK servers.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Arma Reforger Tools</strong></td><td data-v-92836ea9>Workshop mod manager, config editor and admin-tools integration for Reforger.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Backup Pro</strong></td><td data-v-92836ea9>Scheduled server backups to S3-compatible storage with a full restore flow.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Bedrock Addon Installer</strong></td><td data-v-92836ea9>One-click Bedrock behavior/resource packs, scripts and world templates.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Bedrock Version Changer</strong></td><td data-v-92836ea9>Switch Bedrock servers between Vanilla BDS and PocketMine-MP builds.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Database Manager</strong></td><td data-v-92836ea9>Import and export for panel-managed server MySQL databases.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>FastDL Manager</strong></td><td data-v-92836ea9>Per-node FastDL URLs with one-click <code data-v-92836ea9>sv_downloadurl</code> config sync.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>FiveM Utils</strong></td><td data-v-92836ea9>Cache cleaner, game build, txAdmin, artifact and MySQL helpers for FiveM.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Git Source Control</strong></td><td data-v-92836ea9>Clone, stage, commit, pull and push from the server page.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Hytale Mod Installer</strong></td><td data-v-92836ea9>Browse and install Hytale mods from the CurseForge catalogue.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Hytale World Manager</strong></td><td data-v-92836ea9>Install, activate and remove Hytale worlds from the server page.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Mod Installer</strong></td><td data-v-92836ea9>Browse and install Minecraft mods from Modrinth and CurseForge.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Modpack Installer</strong></td><td data-v-92836ea9>One-click Modrinth and CurseForge modpack installs from the file manager.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Node Stats</strong></td><td data-v-92836ea9>Node analytics: historical tracking, capacity planning, and forecasting.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Permission Manager</strong></td><td data-v-92836ea9>Staff roles with a restricted admin area — no <code data-v-92836ea9>root_admin</code> required.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Player List</strong></td><td data-v-92836ea9>Live online-player list with a count badge on the server console.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Player Manager</strong></td><td data-v-92836ea9>Full Minecraft Java player management over plain RCON, nothing on the node.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Plugin Installer</strong></td><td data-v-92836ea9>Browse, install, and manage Minecraft plugins from live catalogues.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Reverse Proxy</strong></td><td data-v-92836ea9>Tracked domain-to-allocation proxy rules with SSL modes and DNS checks.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Server Importer</strong></td><td data-v-92836ea9>Move servers from another Pterodactyl panel via the source&#39;s Application API.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Server Properties</strong></td><td data-v-92836ea9>Categorized server.properties editor with MOTD, icon and YAML editors.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Server Splitter</strong></td><td data-v-92836ea9>Split one server&#39;s resources into sub-servers on the same node.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Server Type Changer</strong></td><td data-v-92836ea9>Guided nest/egg switches with backup/wipe options and per-server whitelists.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Staff Requests</strong></td><td data-v-92836ea9>Users request server access from each other with owner approval.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Subdomain Manager</strong></td><td data-v-92836ea9>Self-service DNS A, CNAME and SRV subdomains for game servers.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Version Changer</strong></td><td data-v-92836ea9>Change the Minecraft: Java Edition software and version of a server.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>Votifier Tester</strong></td><td data-v-92836ea9>Send a real test vote to a Votifier/NuVotifier listener and see the result.</td></tr><tr data-v-92836ea9><td data-v-92836ea9><strong data-v-92836ea9>World Manager</strong></td><td data-v-92836ea9>Install CurseForge worlds and switch the server&#39;s active world directory.</td></tr></tbody></table><hr data-v-92836ea9><h2 id="works-with-the-glacier-theme" tabindex="-1" data-v-92836ea9>Works with the Glacier theme <a class="header-anchor" href="#works-with-the-glacier-theme" aria-label="Permalink to &quot;Works with the Glacier theme&quot;" data-v-92836ea9>​</a></h2><p data-v-92836ea9>Every addon&#39;s client-facing UI is <strong data-v-92836ea9>Glacier-compatible</strong>: styles reference the theme&#39;s design tokens through <code data-v-92836ea9>var(--gl-*, fallback)</code> chains, so with the <a href="./../glacier/" data-v-92836ea9>Glacier theme</a> installed, addon surfaces inherit its accent color, surfaces, borders and radius automatically — in both dark and light mode. Without Glacier, the fallback values render each addon&#39;s own standalone look, pixel-identical to how it shipped. Nothing is required, nothing breaks either way.</p><div class="info custom-block" data-v-92836ea9><p class="custom-block-title" data-v-92836ea9>INFO</p><p data-v-92836ea9>Glacier compatibility applies to <strong data-v-92836ea9>client-facing</strong> surfaces only (server pages, account area, login page). The hub and the admin area are styled by the hub&#39;s own stylesheet, independent of any theme.</p></div><hr data-v-92836ea9><h2 id="next-steps" tabindex="-1" data-v-92836ea9>Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;" data-v-92836ea9>​</a></h2><ul data-v-92836ea9><li data-v-92836ea9><strong data-v-92836ea9><a href="./getting-started/installation" data-v-92836ea9>Installation →</a></strong> — prerequisites, hub install, per-addon install, verify, uninstall.</li><li data-v-92836ea9><strong data-v-92836ea9><a href="./getting-started/quick-start" data-v-92836ea9>Quick Start →</a></strong> — hub plus three starter addons in minutes.</li><li data-v-92836ea9><strong data-v-92836ea9><a href="./configuration/reference" data-v-92836ea9>Configuration Reference →</a></strong> — every setting, every default, per addon.</li><li data-v-92836ea9><strong data-v-92836ea9><a href="./user-guide/dashboard" data-v-92836ea9>The Hub Dashboard →</a></strong> — a tour of the unified admin UI.</li><li data-v-92836ea9><strong data-v-92836ea9><a href="./architecture/overview" data-v-92836ea9>Architecture →</a></strong> — how the packaging format and hub contract work.</li></ul><hr data-v-92836ea9><div class="footer-note" data-v-92836ea9><p data-v-92836ea9><strong data-v-92836ea9>Developed for <a href="https://studio.pingless.org" target="_blank" rel="noreferrer" data-v-92836ea9>PingLess Studios</a></strong></p><p data-v-92836ea9>Questions or licensing — reach us at <a href="https://studio.pingless.org" target="_blank" rel="noreferrer" data-v-92836ea9>studio.pingless.org</a>.</p></div>',26))])}const w=s(h,[["render",g],["__scopeId","data-v-92836ea9"]]);export{y as __pageData,w as default};
